CREATE TABLE ai_allowance_policies (id TEXT PRIMARY KEY, version INTEGER NOT NULL DEFAULT 1, settings JSONB NOT NULL, updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO ai_allowance_policies (id,settings) VALUES ('global','{"personalDailyRequests":10,"professionalDailyRequests":10,"personalTokenAllowance":100000,"professionalTokenAllowance":100000,"tokenResetCadence":"DAILY","resetTime":"00:00","timeZone":"UTC","monthlyResetDay":1,"maxTokensPerRequest":12000,"maxOutputTokens":2048,"globalDailyRequests":30,"globalTotalRequests":1000,"warningPercent":80}');
CREATE TABLE ai_allowance_accounts (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE RESTRICT, version INTEGER NOT NULL DEFAULT 1, daily_request_override INTEGER CHECK (daily_request_override>=0), token_allowance_override INTEGER CHECK (token_allowance_override>=0), created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_allowance_windows (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, kind VARCHAR(16) NOT NULL CHECK(kind IN ('REQUEST','TOKEN')), starts_at TIMESTAMP(3) NOT NULL, ends_at TIMESTAMP(3) NOT NULL, used_units INTEGER NOT NULL DEFAULT 0 CHECK(used_units>=0), reserved_units INTEGER NOT NULL DEFAULT 0 CHECK(reserved_units>=0), bonus_units INTEGER NOT NULL DEFAULT 0, CHECK(ends_at>starts_at), UNIQUE(user_id,kind,starts_at), UNIQUE(id,user_id));
CREATE INDEX ai_allowance_windows_user_id_kind_ends_at_idx ON ai_allowance_windows(user_id,kind,ends_at);
CREATE TABLE ai_allowance_reservations (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, resource_kind VARCHAR(16) NOT NULL CHECK(resource_kind IN ('CHAT','DOCUMENT')), resource_id TEXT NOT NULL, request_window_id TEXT NOT NULL, token_window_id TEXT NOT NULL, reserved_tokens INTEGER NOT NULL CHECK(reserved_tokens>0), max_output_tokens INTEGER NOT NULL CHECK(max_output_tokens>0), state VARCHAR(16) NOT NULL DEFAULT 'RESERVED' CHECK(state IN ('RESERVED','DISPATCHED','SETTLED','RELEASED','UNCERTAIN')), input_tokens INTEGER CHECK(input_tokens>=0), output_tokens INTEGER CHECK(output_tokens>=0), total_tokens INTEGER CHECK(total_tokens>=0), created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, dispatched_at TIMESTAMP(3), settled_at TIMESTAMP(3), UNIQUE(resource_kind,resource_id));
CREATE INDEX ai_allowance_reservations_user_id_state_created_at_idx ON ai_allowance_reservations(user_id,state,created_at);
CREATE TABLE ai_allowance_ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, window_id TEXT NOT NULL, event_key VARCHAR(180) NOT NULL UNIQUE, type VARCHAR(24) NOT NULL, used_delta INTEGER NOT NULL DEFAULT 0, reserved_delta INTEGER NOT NULL DEFAULT 0, bonus_delta INTEGER NOT NULL DEFAULT 0, metadata JSONB, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ai_allowance_ledger_user_id_created_at_idx ON ai_allowance_ledger(user_id,created_at);
CREATE FUNCTION protect_ai_allowance_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'AI allowance ledger is append-only'; END $$;
CREATE TRIGGER ai_allowance_ledger_immutable BEFORE UPDATE OR DELETE ON ai_allowance_ledger FOR EACH ROW EXECUTE FUNCTION protect_ai_allowance_ledger();
ALTER TABLE ai_allowance_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_allowance_windows ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_allowance_reservations ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_allowance_ledger ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_allowance_policies ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_allowance_reservations ADD FOREIGN KEY(request_window_id,user_id) REFERENCES ai_allowance_windows(id,user_id) ON DELETE RESTRICT;
ALTER TABLE ai_allowance_reservations ADD FOREIGN KEY(token_window_id,user_id) REFERENCES ai_allowance_windows(id,user_id) ON DELETE RESTRICT;
ALTER TABLE ai_allowance_ledger ADD FOREIGN KEY(window_id,user_id) REFERENCES ai_allowance_windows(id,user_id) ON DELETE RESTRICT;
